1	// shiftbook 多项弹性预约联合排程与原子创建（schedule-flex）自动化回归测试
2	//
3	// 运行：npm test（本文件随全部测试一起执行）
4	// 说明：
5	// - 使用 Node.js 24 内置测试运行器（node:test），无外部依赖、不访问网络；
6	// - 全部经命令行入口（node app.ts --data <临时文件>）操作，不读取用户默认数据文件；
7	// - 每个场景使用独立临时数据目录，保存结果由新进程查询（list-bookings 等）；
8	// - 覆盖：前项换资源或延后才有解（不逐项贪选最早）、整体无解（含各自可行
9	//   整体不可行）、多方案按清单顺序的取舍（先开始分钟、再按组序资源标识字典序）、
10	//   跨日窗口与停用端点相接、开放相接合并、各类占用（已取消预约与未兑现候补
11	//   不阻挡）、真实保存失败与重试（标识未消费）、重复提交即新请求、新进程查询
12	//   持久安排并独立改期/取消、不加入系列且不自动处理候补、用法与非法清单退出码、
13	//   损坏数据与旧格式文件；
14	// - 任一断言失败即非零退出，输出中标注场景与步骤；结束后自动清理临时文件。
15	
16	import {test} from 'node:test';
17	import assert from 'node:assert/strict';
18	import {spawnSync} from 'node:child_process';
19	import {mkdtempSync, rmSync, writeFileSync, readFileSync} from 'node:fs';
20	import {tmpdir} from 'node:os';
21	import {join, dirname} from 'node:path';
22	import {fileURLToPath} from 'node:url';
23	
24	const APP = join(dirname(fileURLToPath(import.meta.url)), '..', 'app.ts');
25	const OPEN_ALL: Array<[string, string]> = [['2026-01-01T00:00', '2027-01-01T00:00']];
26	// 255 字节文件名：保存时临时文件（<名>.<pid>.tmp）必然超出文件名长度上限，
27	// 从而在不调整任何权限的前提下，可重复地触发真实保存失败。
28	const LONG_NAME = 'f'.repeat(250) + '.json';
29	
30	// ---------------------------------------------------------------------------
31	// 基础设施
32	// ---------------------------------------------------------------------------
33	
34	interface CliResult {
35	  status: number;
36	  stdout: string;
37	  stderr: string;
38	}
39	
40	function runCli(dataFile: string, args: string[]): CliResult {
41	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
42	  if (r.error) throw r.error;
43	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
44	}
45	
46	function ok(df: string, args: string[], ctx: string): CliResult {
47	  const r = runCli(df, args);
48	  assert.equal(
49	    r.status,
50	    0,
51	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
52	  );
53	  return r;
54	}
55	
56	function bizFail(df: string, args: string[], ctx: string): CliResult {
57	  const r = runCli(df, args);
58	  assert.equal(
59	    r.status,
60	    1,
61	    `[${ctx}] 期望退出 1，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
62	  );
63	  return r;
64	}
65	
66	function usageFail(df: string, args: string[], ctx: string): CliResult {
67	  const r = runCli(df, args);
68	  assert.equal(
69	    r.status,
70	    2,
71	    `[${ctx}] 期望退出 2，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
72	  );
73	  return r;
74	}
75	
76	function tempDir(t: {after: (fn: () => void) => void}): string {
77	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-schedule-flex-test-'));
78	  t.after(() => rmSync(dir, {recursive: true, force: true}));
79	  return dir;
80	}
81	
82	function addResource(
83	  df: string,
84	  name: string,
85	  open: Array<[string, string]> = OPEN_ALL,
86	  type = 'venue',
87	): void {
88	  const args = ['add-resource', '--type', type, '--name', name];
89	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
90	  ok(df, args, `登记资源 ${name}`);
91	}
92	
93	function writeManifest(dir: string, name: string, items: unknown[]): string {
94	  const p = join(dir, name);
95	  writeFileSync(p, JSON.stringify({items}) + '\n', 'utf8');
96	  return p;
97	}
98	
99	function scheduleFlex(df: string, manifest: string, ctx: string): CliResult {
100	  return ok(df, ['schedule-flex', manifest], ctx);
101	}
102	
103	function readStore(df: string): any {
104	  return JSON.parse(readFileSync(df, 'utf8'));
105	}
106	
107	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
108	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 失败/查询不得改动数据文件（逐字节比对）`);
109	}
110	
111	interface ExpectedItem {
112	  id: string;
113	  start: string;
114	  end: string;
115	  picks: string[];
116	}
117	
118	// 断言联合排程输出：按清单顺序的各项标识、起止时间与按组对应的资源
119	function assertPlan(r: CliResult, expected: ExpectedItem[], ctx: string): void {
120	  assert.match(
121	    r.stdout,
122	    new RegExp(`联合排程成功：已按清单顺序原子创建 ${expected.length} 项预约`),
123	    `[${ctx}] 成功提示\nstdout:\n${r.stdout}`,
124	  );
125	  expected.forEach((e, i) => {
126	    assert.match(
127	      r.stdout,
128	      new RegExp(`- 第 ${i + 1} 项 -> ${e.id}: ${e.start} → ${e.end}`),
129	      `[${ctx}] 第 ${i + 1} 项起止时间\nstdout:\n${r.stdout}`,
130	    );
131	    e.picks.forEach((id, g) => {
132	      assert.match(
133	        r.stdout,
134	        new RegExp(`第 ${g + 1} 组: ${id}（`),
135	        `[${ctx}] 第 ${i + 1} 项第 ${g + 1} 组应选 ${id}\nstdout:\n${r.stdout}`,
136	      );
137	    });
138	  });
139	}
140	
141	// 断言落盘的预约记录：普通预约（无系列归属）、有效、资源集合按标识排序
142	function assertBooking(
143	  df: string,
144	  id: string,
145	  start: string,
146	  end: string,
147	  resourceIds: string[],
148	  ctx: string,
149	): void {
150	  const store = readStore(df);
151	  const b = (store.bookings as any[]).find((x) => x.id === id);
152	  assert.ok(b, `[${ctx}] 应存在预约 ${id}`);
153	  assert.equal(b.start, start, `[${ctx}] ${id} 开始时间`);
154	  assert.equal(b.end, end, `[${ctx}] ${id} 结束时间`);
155	  assert.deepEqual(b.resourceIds, [...resourceIds].sort(), `[${ctx}] ${id} 资源集合`);
156	  assert.equal(b.status, 'active', `[${ctx}] ${id} 状态`);
157	  assert.equal(b.seriesId, undefined, `[${ctx}] ${id} 不加入系列`);
158	}
159	
160	// ---------------------------------------------------------------------------
161	// 1. 前项换资源才有解：不能逐项贪选较小标识；候选书写顺序不影响结果
162	// ---------------------------------------------------------------------------
163	
164	test('前项换资源才有解：第 1 项须让出 R0001，组内候选书写顺序不影响结果', (t) => {
165	  const dir = tempDir(t);
166	
167	  // (a) 第 1 组若贪选 R0001，第 2 项（只有 R0001）将无可选：必须回溯让第 1 项改选 R0002
168	  const df = join(dir, 'a.json');
169	  addResource(df, '一号会议室'); // R0001
170	  addResource(df, '二号会议室'); // R0002
171	  const m1 = writeManifest(dir, 'plan-a.json', [
172	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001', 'R0002']]},
173	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
174	  ]);
175	  const r1 = scheduleFlex(df, m1, '前项换资源');
176	  assertPlan(
177	    r1,
178	    [
179	      {id: 'B0001', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0002']},
180	      {id: 'B0002', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']},
181	    ],
182	    '前项换资源',
183	  );
184	  assertBooking(df, 'B0001', '2026-10-12T09:00', '2026-10-12T10:00', ['R0002'], '落盘');
185	  assertBooking(df, 'B0002', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '落盘');
186	
187	  // (b) 组内候选倒序书写，结果不变
188	  const df2 = join(dir, 'b.json');
189	  addResource(df2, '一号会议室');
190	  addResource(df2, '二号会议室');
191	  const m2 = writeManifest(dir, 'plan-b.json', [
192	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0002', 'R0001']]},
193	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
194	  ]);
195	  const r2 = scheduleFlex(df2, m2, '候选倒序');
196	  assertPlan(
197	    r2,
198	    [
199	      {id: 'B0001', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0002']},
200	      {id: 'B0002', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']},
201	    ],
202	    '候选倒序结果一致',
203	  );
204	});
205	
206	// ---------------------------------------------------------------------------
207	// 2. 前项延后才有解：清单顺序不限定活动发生先后
208	// ---------------------------------------------------------------------------
209	
210	test('前项延后才有解：第 1 项被后项的占用顶到 10:00，仍按清单顺序取舍', (t) => {
211	  const dir = tempDir(t);
212	  const df = join(dir, 'data.json');
213	  addResource(df, '唯一会议室'); // R0001
214	
215	  // 第 2 项窗口恰等于时长，只能占 09:00-10:00；第 1 项若取最早 09:00 则整体无解，
216	  // 必须延后到 10:00（其开始 = 第 2 项占用结束）
217	  const m = writeManifest(dir, 'plan.json', [
218	    {window: '2026-10-12T09:00/2026-10-12T12:00', duration: 90, groups: [['R0001']]},
219	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
220	  ]);
221	  const r = scheduleFlex(df, m, '前项延后');
222	  assertPlan(
223	    r,
224	    [
225	      {id: 'B0001', start: '2026-10-12T10:00', end: '2026-10-12T11:30', picks: ['R0001']},
226	      {id: 'B0002', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']},
227	    ],
228	    '前项延后',
229	  );
230	  assertBooking(df, 'B0001', '2026-10-12T10:00', '2026-10-12T11:30', ['R0001'], '落盘');
231	  assertBooking(df, 'B0002', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '落盘');
232	});
233	
234	// ---------------------------------------------------------------------------
235	// 3. 整体无解：明确提示、退出 1、不保存部分方案、不消耗标识；含各自可行整体不可行
236	// ---------------------------------------------------------------------------
237	
238	test('整体无解：退出 1 且明确提示，不产生记录/占用/计数变化，后续可行请求标识不被消费', (t) => {
239	  const dir = tempDir(t);
240	  const df = join(dir, 'data.json');
241	  addResource(df, '一号会议室'); // R0001
242	  addResource(df, '二号会议室'); // R0002
243	
244	  // 各自可行但整体不可行：两项可瓜分 R0001/R0002，第三项（只要 R0001）再无资源
245	  const mBad = writeManifest(dir, 'bad.json', [
246	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001', 'R0002']]},
247	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001', 'R0002']]},
248	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
249	  ]);
250	  const bytesBefore = readFileSync(df);
251	  const r1 = bizFail(df, ['schedule-flex', mBad], '整体无解');
252	  assert.match(r1.stderr, /无整体解/, '明确提示无整体解');
253	  assert.ok(!r1.stdout.includes('联合排程成功'), '不报告成功');
254	  assertFileBytes(df, bytesBefore, '无解后');
255	  let store = readStore(df);
256	  assert.equal(store.bookings.length, 0, '不保存部分方案');
257	  assert.equal(store.bookingSeq, 0, '标识计数不变');
258	
259	  // 同一资源被两项全程争抢也无解（窗口恰等于时长）
260	  const mBad2 = writeManifest(dir, 'bad2.json', [
261	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
262	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001']]},
263	  ]);
264	  const r2 = bizFail(df, ['schedule-flex', mBad2], '同一资源两次争抢');
265	  assert.match(r2.stderr, /无整体解/);
266	  assertFileBytes(df, bytesBefore, '再次无解后');
267	
268	  // 失败不消耗标识：随后可行请求仍从 B0001 开始
269	  const mOk = writeManifest(dir, 'ok.json', [
270	    {window: '2026-10-12T09:00/2026-10-12T10:00', duration: 60, groups: [['R0001', 'R0002']]},
271	  ]);
272	  const r3 = scheduleFlex(df, mOk, '无解后的可行请求');
273	  assertPlan(r3, [{id: 'B0001', start: '2026-10-12T09:00', end: '2026-10-12T10:00', picks: ['R0001']}], '标识未消费');
274	  store = readStore(df);
275	  assert.equal(store.bookings.length, 1, '仅本次一项预约');
276	  assert.equal(store.bookingSeq, 1);
277	});
278	
279	// ---------------------------------------------------------------------------
280	// 4. 方案取舍：逐项先比开始分钟，再按需求组顺序比资源标识字典序
281	// ---------------------------------------------------------------------------
282	
283	test('方案取舍：更早开始优先于更小标识；同开始按组序取字典序最小序列', (t) => {
284	  const dir = tempDir(t);
285	
286	  // (a) R0001 标识更小但 10:00 才开放；R0002 08:00 即可用：取更早开始（R0002）
287	  const df1 = join(dir, 'a.json');
288	  addResource(df1, '晚开放场地', [['2026-10-12T10:00', '2026-10-12T20:00']]); // R0001
289	  addResource(df1, '早开放场地', [['2026-10-12T08:00', '2026-10-12T20:00']]); // R0002
290	  const m1 = writeManifest(dir, 'plan-a.json', [
291	    {window: '2026-10-12T08:00/2026-10-12T12:00', duration: 60, groups: [['R0001', 'R0002']]},
292	  ]);
293	  const r1 = scheduleFlex(df1, m1, '更早开始优先');
294	  assertPlan(r1, [{id: 'B0001', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0002']}], '更早开始优先');
295	
296	  // (b) 两项同窗口同候选：第 1 项同开始取字典序最小序列，第 2 项取剩余最小
297	  const df2 = join(dir, 'b.json');
298	  addResource(df2, '甲'); // R0001
299	  addResource(df2, '乙'); // R0002
300	  const m2 = writeManifest(dir, 'plan-b.json', [
301	    {window: '2026-10-12T08:00/2026-10-12T12:00', duration: 60, groups: [['R0001', 'R0002']]},
302	    {window: '2026-10-12T08:00/2026-10-12T12:00', duration: 60, groups: [['R0001', 'R0002']]},
303	  ]);
304	  const r2 = scheduleFlex(df2, m2, '同开始字典序');
305	  assertPlan(
306	    r2,
307	    [
308	      {id: 'B0001', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0001']},
309	      {id: 'B0002', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0002']},
310	    ],
311	    '同开始字典序',
312	  );
313	
314	  // (c) 第 1 项固定后，第 2 项先比开始分钟再比资源：08:00 的 R0002 胜过 09:00 的 R0001
315	  const df3 = join(dir, 'c.json');
316	  addResource(df3, '甲'); // R0001
317	  addResource(df3, '乙'); // R0002
318	  const m3 = writeManifest(dir, 'plan-c.json', [
319	    {window: '2026-10-12T08:00/2026-10-12T12:00', duration: 60, groups: [['R0001']]},
320	    {window: '2026-10-12T08:00/2026-10-12T12:00', duration: 60, groups: [['R0001', 'R0002']]},
321	  ]);
322	  const r3 = scheduleFlex(df3, m3, '后项先比开始');
323	  assertPlan(
324	    r3,
325	    [
326	      {id: 'B0001', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0001']},
327	      {id: 'B0002', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0002']},
328	    ],
329	    '后项先比开始',
330	  );
331	
332	  // (d) 多需求组：同开始按组顺序逐位比较资源标识
333	  const df4 = join(dir, 'd.json');
334	  addResource(df4, '甲'); // R0001
335	  addResource(df4, '乙'); // R0002
336	  addResource(df4, '丙'); // R0003
337	  const m4 = writeManifest(dir, 'plan-d.json', [
338	    {
339	      window: '2026-10-12T08:00/2026-10-12T12:00',
340	      duration: 60,
341	      groups: [
342	        ['R0002', 'R0003'],
343	        ['R0001', 'R0002'],
344	      ],
345	    },
346	  ]);
347	  const r4 = scheduleFlex(df4, m4, '多组字典序');
348	  // 第 1 组最小可选 R0002，第 2 组随后取 R0001（[R0002,R0001] < [R0003,R0001]）
349	  assertPlan(r4, [{id: 'B0001', start: '2026-10-12T08:00', end: '2026-10-12T09:00', picks: ['R0002', 'R0001']}], '多组字典序');
350	  assertBooking(df4, 'B0001', '2026-10-12T08:00', '2026-10-12T09:00', ['R0001', 'R0002'], '落盘资源集合排序');
351	});
352	
353	// ---------------------------------------------------------------------------
354	// 5. 跨日窗口、停用端点相接与开放相接合并
355	// ---------------------------------------------------------------------------
356	
357	test('跨日窗口：结束贴停用起点、开始贴停用终点均可行；相接开放先合并', (t) => {
358	  const dir = tempDir(t);
359	  const df = join(dir, 'data.json');
360	  addResource(df, '跨日场地', [['2026-10-12T08:00', '2026-10-13T20:00']]); // R0001
361	  // 两段相接开放应合并为连续开放（预约可跨越 12:00 接缝）
362	  addResource(df, '分段开放场地', [
363	    ['2026-10-12T08:00', '2026-10-12T12:00'],
364	    ['2026-10-12T12:00', '2026-10-12T20:00'],
365	  ]); // R0002
366	  ok(
367	    df,
