3162	// 多项弹性预约的联合排程与原子创建（schedule-flex）
3163	//
3164	// 读取本地 JSON 清单（{"items": [...]}，非空、有顺序），每项给出营业地时间窗口、
3165	// 所需连续分钟数与有顺序的需求组（每组列出一个可任选其一的候选资源数组）。
3166	// 为整份清单寻找同时可行的安排：每项完整落在自身窗口内，每组恰选一个候选，
3167	// 一项所选资源互不相同并全程固定（不换资源、不拼接间断）；新项之间仅共同资源
3168	// 的左闭右开时间重叠才冲突，端点相接可行。多个完整方案按清单顺序逐项比较：
3169	// 先比该项开始分钟，再按需求组顺序以字符串字典序比资源标识，第一处差异取
3170	// 较小者，随后才比较下一项（清单顺序只用于取舍，不限定活动发生先后）。
3171	// 有解时按清单顺序各创建一项普通预约（稳定、不复用标识，不加入系列、不改动
3172	// 既有预约与候补、不自动处理候补），原子保存全部预约后才报告成功；无整体解
3173	// 明确提示并退出 1，不保存部分方案。每次提交都是新的创建请求，不按清单路径
3174	// 或内容去重。
3175	//
3176	// 求解不逐项贪选最早：项 i 的开始分钟若被项 j 的占用“顶住”，则 s_i = s_j + d_j，
3177	// 故候选开始分钟取“基础空闲段起点”与“其他项占用结束（s_j + d_j）”的闭包
3178	// （仅候选资源集合有交集的项之间传播；按开始分钟归纳，最小方案的每个开始都
3179	// 落在该闭包内）。随后按清单顺序深度优先逐项试探：开始分钟升序、同一开始的
3180	// 资源序列按字典序升序枚举，首个完整方案即按上述比较的最小方案——不会因为
3181	// 逐项固定最早选择而漏掉须调整前项时间或资源的解，也不跳过受阻项。
3182	// ---------------------------------------------------------------------------
3183	
3184	interface FlexPlanItem {
3185	  index: number; // 1 基清单序号
3186	  startRaw: string; // 窗口开始（YYYY-MM-DDTHH:mm）
3187	  endRaw: string; // 窗口结束
3188	  startMin: number;
3189	  endMin: number;
3190	  duration: number; // 所需连续分钟数（正整数，不超过窗口长度）
3191	  groups: RequirementGroup[]; // 有顺序的需求组，每组恰选一个候选
3192	}
3193	
3194	interface FlexPlacement {
3195	  startMin: number;
3196	  endMin: number;
3197	  picks: string[]; // 按需求组顺序的所选资源
3198	}
