3311	      }
3312	      if (dupes.length > 0) {
3313	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3314	        ok = false;
3315	      }
3316	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3317	      if (unknown.length > 0) {
3318	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3319	        ok = false;
3320	      }
3321	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3322	    });
3323	
3324	    if (!ok || win === null) return null;
3325	    return {
3326	      index: idx + 1,
3327	      startRaw: win.start,
3328	      endRaw: win.end,
3329	      startMin: win.startMin,
3330	      endMin: win.endMin,
3331	      duration,
3332	      groups,
3333	    };
3334	  });
3335	  if (problems.length > 0) {
3336	    throw new BizError(`预约清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3337	  }
3338	  return items as FlexPlanItem[];
3339	}
3340	
3341	// 固定开始分钟上，按需求组顺序字典序升序枚举全部可行资源序列
3342	// （每组恰选一个候选，全部所选互不相同；候选已按标识排序）
3343	function* assignmentsInLexOrder(
3344	  groups: RequirementGroup[],
3345	  usable: (id: string) => boolean,
3346	): Generator<string[], void, undefined> {
3347	  const used = new Set<string>();
3348	  const acc: string[] = [];
3349	  function* rec(g: number): Generator<string[], void, undefined> {
3350	    if (g === groups.length) {
3351	      yield [...acc];
3352	      return;
3353	    }
3354	    for (const id of groups[g].candidates) {
3355	      if (used.has(id) || !usable(id)) continue;
3356	      used.add(id);
3357	      acc.push(id);
3358	      yield* rec(g + 1);
3359	      acc.pop();
3360	      used.delete(id);
3361	    }
3362	  }
3363	  yield* rec(0);
3364	}
3365	
3366	// 联合求解：找到即返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
3367	// 逐项（清单顺序）深度优先：开始分钟升序、同一开始的资源序列字典序升序，
3368	// 首个完整方案即“逐项先比开始分钟、再比资源序列”的最小方案。
3369	function solveFlexPlan(store: Store, items: FlexPlanItem[]): FlexPlacement[] | null {
3370	  // 每项各候选资源的基础空闲段：实际可用时间（开放合并后扣除有效停用并集）
3371	  // 裁进自身窗口，再扣除当前有效预约占用（已取消预约/停用与未兑现候补不阻挡）
3372	  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
3373	    const m = new Map<string, Array<[number, number]>>();
3374	    for (const g of it.groups) {
3375	      for (const id of g.candidates) {
3376	        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin));
3377	      }
3378	    }
3379	    return m;
3380	  });
3381	
3382	  // 候选开始分钟闭包：基础空闲段起点，加上“被其他项占用结束顶住”的起点
3383	  // s_i = s_j + d_j（仅候选资源集合有交集的项之间传播；值域有限，必收敛）
3384	  const candidateIds = items.map((it) => {
3385	    const set = new Set<string>();
3386	    for (const g of it.groups) for (const id of g.candidates) set.add(id);
3387	    return set;
3388	  });
3389	  const sharesCandidate = (a: number, b: number): boolean => {
3390	    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
3391	    return false;
3392	  };
3393	  const candStarts: Array<Set<number>> = items.map((it, i) => {
3394	    const set = new Set<number>();
3395	    for (const segs of baseFree[i].values()) {
3396	      for (const [s] of segs) {
3397	        if (s + it.duration <= it.endMin) set.add(s);
3398	      }
3399	    }
3400	    return set;
3401	  });
3402	  let changed = true;
3403	  while (changed) {
3404	    changed = false;
3405	    for (let j = 0; j < items.length; j++) {
3406	      for (let i = 0; i < items.length; i++) {
3407	        if (i === j || !sharesCandidate(i, j)) continue;
3408	        for (const s of candStarts[j]) {
3409	          const t = s + items[j].duration;
3410	          if (
3411	            t >= items[i].startMin &&
3412	            t + items[i].duration <= items[i].endMin &&
3413	            !candStarts[i].has(t)
3414	          ) {
3415	            candStarts[i].add(t);
3416	            changed = true;
3417	          }
3418	        }
3419	      }
3420	    }
3421	  }
3422	
3423	  // 已放置项对各资源的占用（随试探入栈/出栈增减）
3424	  const occById = new Map<string, Array<[number, number]>>();
3425	
3426	  const search = (idx: number): FlexPlacement[] | null => {
3427	    if (idx === items.length) return [];
3428	    const it = items[idx];
3429	    // 当前空闲段 = 基础空闲段扣除已放置项占用
3430	    const freeById = new Map<string, Array<[number, number]>>();
3431	    for (const [id, segs] of baseFree[idx]) {
3432	      const occ = occById.get(id);
3433	      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
3434	    }
3435	    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
3436	      const e = s + it.duration;
3437	      const cache = new Map<string, boolean>();
3438	      const usable = (id: string): boolean => {
3439	        let v = cache.get(id);
3440	        if (v === undefined) {
3441	          v = isFullyCovered(freeById.get(id)!, s, e);
3442	          cache.set(id, v);
3443	        }
3444	        return v;
3445	      };
3446	      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
3447	        for (const id of picks) {
3448	          const occ = occById.get(id) ?? [];
3449	          occ.push([s, e]);
3450	          occById.set(id, occ);
3451	        }
3452	        const rest = search(idx + 1);
3453	        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
3454	        for (const id of picks) occById.get(id)!.pop();
3455	      }
3456	    }
3457	    return null;
3458	  };
3459	
3460	  return search(0);
3461	}
3462	
3463	async function cmdScheduleFlex(args: string[]): Promise<void> {
3464	  const {values, positionals} = parseFlags(args, []);
3465	  if (values.size > 0) {
3466	    throw new UsageError(
3467	      `schedule-flex 不接受选项: ${[...values.keys()].map((k) => '--' + k).join(' ')}`,
3468	    );
3469	  }
3470	  if (positionals.length !== 1) {
3471	    throw new UsageError('用法: schedule-flex <预约清单文件>');
3472	  }
3473	  const manifestFile = positionals[0];
3474	
3475	  // 修改入口：先取得写入保护再读最新数据，排程至保存全程受保护
3476	  const file = activeDataFile;
3477	  const store = await loadStoreForWrite(file);
3478	  const records = parseFlexPlanShape(await loadFlexManifest(manifestFile), manifestFile);
3479	  const items = parseFlexPlanItems(store, records, manifestFile);
3480	
3481	  const plan = solveFlexPlan(store, items);
3482	  if (plan === null) {
3483	    throw new BizError(
3484	      `无整体解：清单 ${manifestFile} 的 ${items.length} 项预约不存在同时可行的安排` +
3485	        '（每项须完整落在自身窗口内，各组所选资源互不相同并全程固定，' +
3486	        '新项之间共同资源时间不得重叠）。未创建任何预约，数据文件未改动。',
3487	    );
3488	  }
3489	
3490	  // 全部校验与求解通过：按清单顺序分配稳定且不复用的预约标识，一次原子保存
3491	  const created: Array<{id: string; start: string; end: string; picks: string[]}> = [];
3492	  plan.forEach((p) => {
3493	    const start = formatDateTime(p.startMin);
3494	    const end = formatDateTime(p.endMin);
3495	    if (start === null || end === null) {
3496	      // 理论不可达：窗口已校验在 0001-9999 内，时段不超出窗口
3497	      throw new BizError('可行时段超出四位年份范围');
3498	    }
3499	    store.bookingSeq += 1;
3500	    const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
3501	    store.bookings.push({id, resourceIds: [...p.picks].sort(), start, end, status: 'active'});
3502	    created.push({id, start, end, picks: p.picks});
3503	  });
3504	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
3505	  await saveStore(file, store);
3506	
3507	  console.log(`联合排程成功：已按清单顺序原子创建 ${created.length} 项预约`);
3508	  created.forEach((c, i) => {
3509	    console.log(`- 第 ${i + 1} 项 -> ${c.id}: ${c.start} → ${c.end}（${items[i].duration} 分钟）`);
3510	    c.picks.forEach((id, g) => {
3511	      const r = store.resources.find((x) => x.id === id)!;
3512	      console.log(`    第 ${g + 1} 组: ${id}（${r.name}，${RESOURCE_TYPE_LABEL[r.type]}）`);
3513	    });
3514	  });
3515	}
3516	
3517	// ---------------------------------------------------------------------------
3518	// 资源使用率与繁忙时段统计（usage-stats，只读）
3519	//
3520	// 统计窗口内所选资源的实际可用、占用、空闲分钟与使用率（逐日 + 整窗），
3521	// 并给出同时被占用的所选资源数量峰值及全部达到峰值的最大连续区间。
3522	// 实际可用时间 = 开放区间合并重叠或相接后扣除有效停用并集，再裁剪到窗口；
3523	// 占用只计有效预约（普通、系列成员、导入、候补兑现同口径；已取消预约/停用、
3524	// 未兑现候补、导入首次请求快照与改期历史快照均不计）的当前时间与当前资源，
3525	// 并取与实际可用区间的交集，同一资源的重叠占用合并、一分钟只计一次。
3526	// 本命令只读一份完整快照：不取写入保护、不写数据文件、不推进任何计数。
3527	// ---------------------------------------------------------------------------
3528	
3529	// 一组互不相交区间的总分钟数
3530	function totalMinutes(segments: Array<[number, number]>): number {
3531	  return segments.reduce((sum, [s, e]) => sum + (e - s), 0);
3532	}
3533	
3534	// 使用率百分比：占用/可用，四舍五入至两位小数；分母为零显示“不适用”
3535	function formatUsagePercent(occupied: number, available: number): string {
3536	  if (available === 0) return '不适用';
3537	  return `${(Math.round((occupied * 10000) / available) / 100).toFixed(2)}%`;
3538	}
3539	
3540	// 营业地日历日序号 -> YYYY-MM-DD（与机器时区无关；调用方保证年份在 0001-9999 内）
3541	function formatBusinessDate(dayIndex: number): string {
3542	  const {y, m, d} = civilFromDays(dayIndex);
3543	  return `${String(y).padStart(4, '0')}-${pad2(m)}-${pad2(d)}`;
3544	}
3545	
3546	// 某资源在窗口内的占用区间：全部有效预约按当前时间与当前资源裁剪进窗口，
3547	// 再与实际可用区间求交；同一资源的重叠占用合并，一分钟只计一次
3548	function occupiedSegmentsOf(
3549	  store: Store,
3550	  resourceId: string,
3551	  available: Array<[number, number]>,
3552	  wStart: number,
3553	  wEnd: number,
3554	): Array<[number, number]> {
3555	  const raw: Array<[number, number]> = [];
3556	  for (const b of store.bookings) {
3557	    if (b.status !== 'active' || !b.resourceIds.includes(resourceId)) continue;
3558	    const bs = parseDateTime(b.start, '预约开始时间');
3559	    const be = parseDateTime(b.end, '预约结束时间');
3560	    const s = Math.max(bs, wStart);
3561	    const e = Math.min(be, wEnd);

